function GachaCoinQuestBgControll:PlayDrawChangeAnimator()
    CfUtils.PlayAnimator(self.BossDrawing, "GachaCoinQuestDialogBg")
end

function GachaCoinQuestBgControll:PlayDrawMoveAnimator(targetQuestType)
    if targetQuestType == GCQConstants.Defines.QuestType.Challenge then
        CfUtils.PlayAnimator(self.BossDrawing, "Go")
    elseif targetQuestType == GCQConstants.Defines.QuestType.Normal then
        CfUtils.PlayAnimator(self.BossDrawing, "Back")
    end
end

